import Metal
import QuartzCore
import ScreenSaver
import os

private let log = Logger(subsystem: "com.bosse.starfields.metalsaver", category: "saver")

/// Native screen saver (option B): one full-screen Metal fragment shader per
/// frame, generated by impellerc from the app's GLSL - light-speed streaks
/// (shaders/hyperspace_saver.frag) with a periodic jump to light speed
/// (JumpCycle), or the app's Procedural renderer
/// (shaders/procedural_stars.frag). Picked in the options sheet.
///
/// Frames are paced by a display link of the view's own display. In
/// legacyScreenSaver only the main display's view gets a `window.screen` (see
/// the Flutter saver, macos_saver/), so the others find their `NSScreen` by
/// size. The host's animation timer (`animateOneFrame`) is the fallback: it
/// drives all views from one main-thread timer, and a 60 Hz display's
/// blocking `nextDrawable` then made the 120/240 Hz displays judder.
///
/// Built and installed by tool/build_metal_saver.sh.
@objc(StarfieldsMetalSaverView)
final class StarfieldsMetalSaverView: ScreenSaverView {
  private let metalLayer = CAMetalLayer()
  private var settings = SaverSettings.load()
  private lazy var cycle = JumpCycle(settings: settings)
  private var sheet: ConfigureSheet?
  private var procedural = ProceduralLayers()
  private var warpNebula: MTLTexture?  // Warp speed: the gas clouds, a quarter of the drawable
  private var warpHistory: [MTLTexture] = []  // Warp speed: the last two frames, drawable size
  private var warpHistoryIndex = 0  // the one written this frame
  private var cloudTravel = 0.0  // Warp speed: the clouds' travel, integrated per frame
  private var lastWarpTravel: Double?  // Warp speed: last frame's star travel, for the trail's stretch
  private var lensFlare = WarpLensFlare()  // Warp speed: now and then a star with an anamorphic streak
  private var biomes = WarpBiomes()  // Warp speed: the clouds' colors, a new biome per jump
  /// Which stars (and Warp speed's clouds): each view draws its own, so the
  /// displays don't all show the same sky. New on every start - the host
  /// often gives a view no screen to tell displays apart by.
  private var seed: Float = 0
  private var lastFrameTime: Double?
  private var startTime: CFTimeInterval = 0
  private var stats = FrameStats()
  private var stopObserver: NSObjectProtocol?
  private var displayLink: AnyObject?  // CADisplayLink (macOS 14+)

  /// The System Settings thumbnail shares the host process with the real
  /// saver. While the saver covers System Settings, the thumbnail's updates
  /// are throttled, and that dragged every view of the process down to
  /// ~3 fps. The real saver arrives as a batch of one view per display,
  /// created after the thumbnail: a view pauses while at least that many
  /// newer views animate. (Asking for ScreenSaverEngine with
  /// NSRunningApplication finds nothing inside the sandboxed host.)
  private static let liveViews = NSHashTable<StarfieldsMetalSaverView>.weakObjects()
  private let createdAt = CACurrentMediaTime()
  private var paused = false
  private var lastPauseCheck: CFTimeInterval = 0
  private var resumedAt: CFTimeInterval?

  override init?(frame: NSRect, isPreview: Bool) {
    super.init(frame: frame, isPreview: isPreview)
    Self.liveViews.add(self)
    log.notice("init frame=\(NSStringFromRect(frame), privacy: .public) preview=\(isPreview)")
    animationTimeInterval = 1.0 / 120.0
    guard let renderer = Renderer.shared else { return nil }
    metalLayer.device = renderer.device
    metalLayer.pixelFormat = .bgra8Unorm
    metalLayer.colorspace = CGColorSpace(name: CGColorSpace.sRGB)
    metalLayer.isOpaque = true
    metalLayer.framebufferOnly = true
    // The host's timer paces the frames; don't let nextDrawable stall it.
    metalLayer.allowsNextDrawableTimeout = true
    metalLayer.backgroundColor = NSColor.black.cgColor
    wantsLayer = true
    layer = metalLayer
  }

  required init?(coder: NSCoder) {
    super.init(coder: coder)
  }

  deinit {
    log.notice("deinit")
  }

  /// Device pixels per point. In legacyScreenSaver only the main display's
  /// view gets a `window.screen`; the other windows report the main display's
  /// scale (2 on a 1x display). Their view fills its display, so the screen
  /// with the same size tells the scale.
  private var backingScale: CGFloat { displayScreen?.backingScaleFactor ?? window?.backingScaleFactor ?? 2 }

  /// The display this view fills: its window's screen, or else the only
  /// screen of the same size.
  private var displayScreen: NSScreen? {
    if let screen = window?.screen { return screen }
    let sameSize = NSScreen.screens.filter { $0.frame.size == bounds.size }
    return sameSize.count == 1 ? sameSize[0] : nil
  }

  /// The host puts each view into a container (a ScreenSaverView) in a
  /// display's window. It once put views into the other display's window
  /// without resizing them (a 1080p picture in a 1440p area), and the
  /// container is sometimes still 0x0 when the view arrives, so autoresizing
  /// alone is not enough (a view kept at its creation size grew by the
  /// container's size: the center ended up top right). The view follows its
  /// container: here and on every frame.
  override func viewDidMoveToSuperview() {
    super.viewDidMoveToSuperview()
    autoresizingMask = [.width, .height]
    fitContainer()
  }

  private func fitContainer() {
    // The host's container is itself a ScreenSaverView; elsewhere (test_host,
    // a window's content view) the window sizes the view.
    guard let container = superview as? ScreenSaverView, frame != container.bounds else { return }
    log.notice("resized to the container: \(NSStringFromRect(self.frame), privacy: .public) -> \(NSStringFromRect(container.bounds), privacy: .public)")
    frame = container.bounds
  }

  override func viewDidChangeBackingProperties() {
    super.viewDidChangeBackingProperties()
    updateDrawableSize()
  }

  override func setFrameSize(_ newSize: NSSize) {
    super.setFrameSize(newSize)
    updateDrawableSize()
  }

  /// Render scale (device pixels per point drawn): at most the display's,
  /// capped per renderer; the layer scales the drawable up.
  /// - Hyperspace 1.5: at light speed the shader checks ~40 cells per pixel;
  ///   at 2x three displays were GPU-bound (51-80 fps), at 1.5x they keep up
  ///   and look the same.
  /// - Procedural 0.5: up to 10 layers x 8 candidate stars per pixel, each
  ///   with exp/cos/sin; three displays ran 12-16 fps at 1.5x, 24 at 1x, 42 at
  ///   0.75x; 0.6x failed at 4000 stars; 0.5x holds 60 fps up to 8000 stars,
  ///   and its soft glows look only slightly softer.
  private var renderScale: CGFloat {
    min(backingScale, Self.renderScaleOverride ?? (settings.renderer == .procedural ? 0.5 : 1.5))
  }

  /// Frames per second at most, on every display: a screen saver need not
  /// burn energy at 120 or 240 Hz. (On the 240 Hz display legacyScreenSaver
  /// also intermittently froze 3/4 of the image, at 120 and 240 fps alike - a
  /// host quirk that moved between displays when their refresh rates changed;
  /// Apple's Flurry, at 60, behaved.) Overridable for testing:
  /// STARFIELDS_MAX_FPS.
  private static let maxFrameRate: Float =
    ProcessInfo.processInfo.environment["STARFIELDS_MAX_FPS"].flatMap(Float.init) ?? 60

  /// For testing: STARFIELDS_RENDER_SCALE.
  private static let renderScaleOverride: CGFloat? =
    ProcessInfo.processInfo.environment["STARFIELDS_RENDER_SCALE"].flatMap(Double.init).map { CGFloat($0) }

  private func updateDrawableSize() {
    metalLayer.contentsScale = backingScale
    metalLayer.drawableSize = CGSize(width: bounds.width * renderScale, height: bounds.height * renderScale)
  }

  override func startAnimation() {
    super.startAnimation()
    // The host may call this again without stopAnimation in between: one
    // display link and observer per view, or it renders several times per frame.
    stopPacing()
    // The settings may have changed in another host process (the System
    // Settings preview) since this view was created; the render scale depends
    // on the renderer.
    settings = SaverSettings.load()
    let screen = window?.screen.map { NSStringFromRect($0.frame) } ?? "none"
    log.notice("startAnimation \(self.settings.renderer.rawValue, privacy: .public) \(Int(self.bounds.width))x\(Int(self.bounds.height)) @\(self.backingScale)x render \(self.renderScale)x screen=\(screen, privacy: .public)")
    logWindow()
    updateDrawableSize()
    startTime = CACurrentMediaTime()
    seed = Float.random(in: 0..<100)
    biomes = WarpBiomes()
    cycle = JumpCycle(settings: settings)
    stats = FrameStats()
    if #available(macOS 14, *), let screen = displayScreen {
      let link = screen.displayLink(target: self, selector: #selector(displayLinkFired))
      link.preferredFrameRateRange = CAFrameRateRange(
        minimum: min(30, Self.maxFrameRate), maximum: Self.maxFrameRate, preferred: Self.maxFrameRate)
      link.add(to: .main, forMode: .common)
      displayLink = link
    }
    log.notice("pacing: \(self.displayLink == nil ? "host timer" : "display link, at most \(Self.maxFrameRate) fps", privacy: .public)")
    stopObserver = DistributedNotificationCenter.default().addObserver(
      forName: NSNotification.Name("com.apple.screensaver.willstop"),
      object: nil,
      queue: .main
    ) { [weak self] _ in
      guard let self else { return }
      // Meant for the real saver: a covered thumbnail stays started, and the
      // saver ending is its cue to resume - the host stops it right after
      // (see stopAnimation), sometimes before the next pause check.
      if self.paused {
        self.paused = false
        self.resumedAt = CACurrentMediaTime()
        log.notice("willstop notification: the saver ends, thumbnail resumes")
        return
      }
      log.notice("willstop notification")
      self.stopAnimation()
    }
    // A new view may complete a set that covers older ones: let them check now.
    for view in Self.liveViews.allObjects where view !== self { view.lastPauseCheck = 0 }
  }

  override func stopAnimation() {
    if stopObserver != nil {
      log.notice("stopAnimation after \(CACurrentMediaTime() - self.startTime, format: .fixed(precision: 1)) s")
    }
    stopPacing()
    super.stopAnimation()
    // When the real saver ends, the host also stops the System Settings
    // thumbnail, right after it resumed, and never starts it again: the
    // preview would stay still. Restart it then; a later stop (System
    // Settings closing) is final.
    if let resumedAt, CACurrentMediaTime() - resumedAt < 2 {
      self.resumedAt = nil
      log.notice("stopped by the host right after the saver ended; restarting the thumbnail")
      DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) { [weak self] in
        guard let self, self.window != nil, !self.isAnimating else { return }
        self.startAnimation()
      }
    }
  }

  private func stopPacing() {
    if let stopObserver {
      DistributedNotificationCenter.default().removeObserver(stopObserver)
      self.stopObserver = nil
    }
    if #available(macOS 14, *) { (displayLink as? CADisplayLink)?.invalidate() }
    displayLink = nil
  }

  /// Diagnostics: what tells the System Settings thumbnail view from a real
  /// display's view (both full size, both without a screen)?
  private func logWindow() {
    guard let window else {
      log.notice("window: none")
      return
    }
    var chain: [String] = []
    var view: NSView? = superview
    while let current = view, chain.count < 6 {
      chain.append(String(describing: type(of: current)))
      view = current.superview
    }
    log.notice(
      "window: \(String(describing: type(of: window)), privacy: .public) frame=\(NSStringFromRect(window.frame), privacy: .public) level=\(window.level.rawValue) visible=\(window.isVisible) occlusionVisible=\(window.occlusionState.contains(.visible)) number=\(window.windowNumber) superviews=\(chain.joined(separator: "<"), privacy: .public)"
    )
  }

  override var hasConfigureSheet: Bool { true }

  override var configureSheet: NSWindow? {
    // System Settings asks the 0x0 isPreview view for the sheet; it lives in
    // another host process than the thumbnail view, which reloads the
    // settings when the host restarts it.
    let sheet = ConfigureSheet(settings: SaverSettings.load()) { settings in
      log.notice("settings saved: \(String(describing: settings), privacy: .public)")
    }
    self.sheet = sheet  // the window's controller must outlive this call
    return sheet.window
  }

  override func draw(_ rect: NSRect) {
    // Layer-backed: drawing happens in animateOneFrame.
  }

  override func animateOneFrame() {
    if displayLink == nil { renderFrame() }
  }

  @available(macOS 14, *)
  @objc private func displayLinkFired(_ link: CADisplayLink) {
    renderFrame()
  }

  /// Whether newer views (a full set, one per display) took over; checked
  /// about once a second.
  private var shouldPause: Bool {
    let now = CACurrentMediaTime()
    if now - lastPauseCheck >= 1 {
      lastPauseCheck = now
      let newer = Self.liveViews.allObjects.filter { $0 !== self && $0.createdAt > createdAt && $0.isAnimating }
      let covered = newer.count >= NSScreen.screens.count
      if covered != paused {
        paused = covered
        resumedAt = covered ? nil : now
        log.notice(
          "\(Int(self.bounds.width))x\(Int(self.bounds.height)) \(covered ? "paused: \(newer.count) newer views run" : "resumed", privacy: .public)"
        )
      }
    }
    return paused
  }

  private func renderFrame() {
    if shouldPause { return }
    fitContainer()
    stats.ticks += 1
    defer {
      if let report = stats.report(now: CACurrentMediaTime()) {
        log.notice("\(Int(self.bounds.width))x\(Int(self.bounds.height)) @\(self.backingScale)x: \(report, privacy: .public)")
      }
    }
    guard let renderer = Renderer.shared else { return }
    let now = CACurrentMediaTime() - startTime
    let cpuStart = CACurrentMediaTime()
    guard let drawable = metalLayer.nextDrawable() else {
      stats.missedDrawables += 1
      return
    }
    let gpuTime: (Double) -> Void = { [weak self] gpuMillis in
      DispatchQueue.main.async { self?.stats.gpuFrame(millis: gpuMillis) }
    }
    switch settings.renderer {
    case .hyperspace: drawHyperspace(renderer, to: drawable, now: now, gpuTime: gpuTime)
    case .procedural: drawProcedural(renderer, to: drawable, now: now, gpuTime: gpuTime)
    case .warp: drawWarp(renderer, to: drawable, now: now, gpuTime: gpuTime)
    }
    stats.frame(cpuMillis: (CACurrentMediaTime() - cpuStart) * 1000)
  }

  /// shaders/hyperspace_saver.frag: impellerc binds each uniform to its own
  /// fragment buffer, in declaration order. FlutterFragCoord in logical pixels.
  private func drawHyperspace(
    _ renderer: Renderer, to drawable: CAMetalDrawable, now: Double, gpuTime: @escaping (Double) -> Void
  ) {
    cycle.update(now)
    let drive = cycle.drive
    let travel = drive.travel(now)
    let state = drive.state(now)
    let wrap = HyperspaceDrive.row * HyperspaceDrive.rowPeriod
    let size = SIMD2(Float(bounds.width), Float(bounds.height))
    // Wrapped in Double so 32-bit GPU floats never see a large value.
    let shift = SIMD4(HyperspaceDrive.layerSpeeds.map { Float(($0 * travel).truncatingRemainder(dividingBy: wrap)) })
    let length = SIMD4(HyperspaceDrive.layerSpeeds.map { Float($0 * HyperspaceDrive.lengthPerSpeed * state.stretch) })
    let density = Float(min(1, settings.stars / HyperspaceDrive.cells))
    renderer.draw(.hyperspace, to: drawable, fragCoordSize: size, gpuTime: gpuTime) { encoder in
      encoder.setFragmentValue(size, index: 0)
      encoder.setFragmentValue(density, index: 1)
      encoder.setFragmentValue(shift, index: 2)
      encoder.setFragmentValue(length, index: 3)
      encoder.setFragmentValue(Float(state.glow), index: 4)
      encoder.setFragmentValue(Float(state.width), index: 5)
      encoder.setFragmentValue(Float(state.boost), index: 6)
      encoder.setFragmentValue(seed, index: 7)
    }
  }

  /// shaders/procedural_saver.frag: the app's Procedural stars at half the
  /// app's speed, tinted blue, with a black center; no jumps and no
  /// explosions (the app's supernova is partly Flutter overlays).
  /// FlutterFragCoord in shader pixels; the shader divides by uScale.
  private func drawProcedural(
    _ renderer: Renderer, to drawable: CAMetalDrawable, now: Double, gpuTime: @escaping (Double) -> Void
  ) {
    let width = Double(bounds.width), height = Double(bounds.height)
    // Half speed: positions scroll at half the rate. Sizes follow the
    // position, so stars still grow the same way along their way out.
    procedural.compute(count: settings.stars, time: now * 0.5, width: width, height: height)
    let scale = Float(renderScale)
    let size = SIMD2(Float(width), Float(height))
    let layers = procedural
    renderer.draw(.procedural, to: drawable, fragCoordSize: size * scale, gpuTime: gpuTime) { encoder in
      encoder.setFragmentValue(size, index: 0)
      encoder.setFragmentValue(scale, index: 1)
      // Explosion: age -1 = none; drop-off and pause unused then.
      encoder.setFragmentValue(SIMD4<Float>(-1, 1.8, 2.5, 0), index: 2)
      encoder.setFragmentArray(layers.layer, index: 3)
      encoder.setFragmentArray(layers.motion, index: 4)
      encoder.setFragmentValue(seed, index: 5)
    }
  }
}

extension StarfieldsMetalSaverView {
  /// WarpSpeed.metal: gas clouds at a quarter of the resolution into
  /// `warpNebula`, then the composite with the stars, which also blends in
  /// the previous frame at warp (temporal feedback, ping-ponging
  /// `warpHistory`). Cruise and warp come from the same JumpCycle as
  /// Hyperspace: its speed drives the travel, its stretch the motion blur,
  /// the speed lines and the feedback.
  fileprivate func drawWarp(
    _ renderer: Renderer, to drawable: CAMetalDrawable, now: Double, gpuTime: @escaping (Double) -> Void
  ) {
    let width = max(1, drawable.texture.width / 4), height = max(1, drawable.texture.height / 4)
    if warpNebula?.width != width || warpNebula?.height != height {
      warpNebula = renderer.makeNebulaTexture(width: width, height: height)
    }
    let fullWidth = drawable.texture.width, fullHeight = drawable.texture.height
    var clearHistory = false
    if warpHistory.first?.width != fullWidth || warpHistory.first?.height != fullHeight {
      warpHistory = (0..<2).compactMap { _ in renderer.makeHistoryTexture(width: fullWidth, height: fullHeight) }
      clearHistory = true
    }
    guard let warpNebula, warpHistory.count == 2 else { return }
    cycle.update(now)
    let state = cycle.drive.state(now)
    // 0 in cruise .. 1 at warp (and while the stars stretch out).
    let stretch = (state.stretch - JumpCycle.cruise.stretch) / (JumpCycle.lightSpeed.stretch - JumpCycle.cruise.stretch)
    let warp = Float(min(max(stretch, 0), 1))
    // The clouds' tunnel (far away -> travelling through them) follows the
    // speed, 0 at cruise .. 1 at light speed: it holds through the brake and
    // comes with the exponential creep, sudden at the end like the stars.
    // (Following the stretch, it all happened while the stars braked.)
    let tunnelSpeed = (state.speed - JumpCycle.cruise.speed) / (JumpCycle.lightSpeed.speed - JumpCycle.cruise.speed)
    let tunnel = min(max(tunnelSpeed, 0), 1)
    // Clouds: barely moving far away in cruise; at warp they rush past (we
    // travel through them). Their speed changes, so their travel is
    // integrated - a changing factor times the total travel would jump.
    let gap = lastFrameTime.map { now - $0 }
    let dt = gap.map { min(max($0, 0), 0.1) } ?? 0
    lastFrameTime = now
    // A fresh start (the clock restarts), or a pause (the covered System
    // Settings thumbnail): last frame's history is stale.
    if gap.map({ $0 < 0 || $0 > 0.25 }) ?? true { clearHistory = true }
    let cloudSpeed = state.speed / JumpCycle.lightSpeed.speed * Self.warpSpeed * (0.3 + 0.9 * tunnel)
    cloudTravel = (cloudTravel + cloudSpeed * dt).truncatingRemainder(dividingBy: 1000)
    // Scaled so that light speed (2.2) travels at the warp speed (1.6).
    let travel = cycle.drive.travel(now) * Self.warpSpeed / JumpCycle.lightSpeed.speed
    let frameTravel = lastWarpTravel.map { min(max(travel - $0, 0), 0.2) } ?? 0
    lastWarpTravel = travel
    // Trail (temporal feedback), at warp only. Its strength also follows the
    // speed: none while the stars brake and stretch out at the start of a
    // jump (they barely move), and it shortens as they slow down dropping
    // out - no ghost image. Per 1/60 s, scaled to this frame's time so its
    // length does not depend on the frame rate.
    let speed = min(state.speed / JumpCycle.lightSpeed.speed, 1)
    let trailWeight = Double(warp) * speed * pow(settings.trail, dt * 60)
    // Stretch: the previous frame zooms outward by a share of this frame's
    // star travel (rho at layer speed 1). The slowest stars move 0.45 of it:
    // a smaller share keeps every echo behind its star, at any speed - a
    // fixed zoom overtook slow stars, and their trail pointed outward.
    let trailZoom = exp(-settings.trailStretch * frameTravel)
    biomes.update(dt: dt, speed: speed, lightSeconds: settings.lightSeconds, drift: Self.colorSpeed)
    let cloudColors = biomes.colors.map { SIMD4($0, 0) }
    let lens = lensFlare.update(
      time: now, travel: travel, speed: speed, size: SIMD2(Double(bounds.width), Double(bounds.height)))
    let uniforms = WarpUniforms(
      size: SIMD2(Float(bounds.width), Float(bounds.height)),
      travel: Float(travel.truncatingRemainder(dividingBy: 1200)),
      density: Float(min(1, settings.stars / Self.warpCells)),
      nebula: 1, emerge: 1,
      blur: warp,
      lines: warp,
      cloudTravel: Float(cloudTravel),
      tunnel: Float(tunnel),
      feedbackDecay: Float(trailWeight),
      feedbackZoom: Float(trailZoom),
      lensPos: lens.position, lensDir: lens.direction, lensRho: lens.rho, lensSize: lens.size,
      lensBright: lens.brightness, lensFlicker: lens.flicker, lensStreaks: lens.streaks, seed: seed,
      colorTime: Float(biomes.colorTime),
      cloud0: cloudColors[0], cloud1: cloudColors[1], cloud2: cloudColors[2])
    let read = warpHistory[1 - warpHistoryIndex], write = warpHistory[warpHistoryIndex]
    warpHistoryIndex = 1 - warpHistoryIndex
    renderer.drawWarp(
      to: drawable, nebula: warpNebula, history: (read: read, write: write), clearHistory: clearHistory,
      uniforms: uniforms, gpuTime: gpuTime)
  }

  /// Travel per second at warp (rho at layer speed 1).
  fileprivate static let warpSpeed = 1.6
  /// The clouds' color drift clock in cruise; STARFIELDS_COLOR_SPEED
  /// fast-forwards it (tests).
  fileprivate static let colorSpeed =
    ProcessInfo.processInfo.environment["STARFIELDS_COLOR_SPEED"].flatMap(Double.init) ?? 1
  /// Star cells over all layers that can show a star (5 layers x 360
  /// columns x ~4.8 rho / 0.32 rho rows); must match WarpSpeed.metal.
  fileprivate static let warpCells = 5.0 * 360 * 4.8 / 0.32
}

/// Must match `WarpUniforms` in WarpSpeed.metal.
private struct WarpUniforms {
  var size: SIMD2<Float>
  var travel: Float
  var density: Float
  var nebula: Float
  var emerge: Float
  var blur: Float
  var lines: Float
  var cloudTravel: Float
  var tunnel: Float
  var feedbackDecay: Float
  var feedbackZoom: Float
  var lensPos: SIMD2<Float>
  var lensDir: SIMD2<Float>
  var lensRho: Float
  var lensSize: Float
  var lensBright: Float
  var lensFlicker: Float
  var lensStreaks: Float
  var seed: Float
  var colorTime: Float
  var padding: Float = 0
  var cloud0: SIMD4<Float>  // cloudColors[3]
  var cloud1: SIMD4<Float>
  var cloud2: SIMD4<Float>
}

extension MTLRenderCommandEncoder {
  fileprivate func setFragmentValue<T>(_ value: T, index: Int) {
    withUnsafeBytes(of: value) { setFragmentBytes($0.baseAddress!, length: $0.count, index: index) }
  }

  fileprivate func setFragmentArray<T>(_ values: [T], index: Int) {
    values.withUnsafeBytes { setFragmentBytes($0.baseAddress!, length: $0.count, index: index) }
  }
}

/// Device, queue and one pipeline per renderer, shared by all views of the
/// host process. The fragment shaders are generated by impellerc from the
/// app's GLSL (tool/build_metal_saver.sh); all are compiled at runtime.
private final class Renderer {
  static let shared: Renderer? = Renderer()

  let device: MTLDevice
  private let queue: MTLCommandQueue
  private let pipelines: [SaverRenderer: MTLRenderPipelineState]
  private let nebulaPipeline: MTLRenderPipelineState  // Warp speed, pass 1
  private let warpPipeline: MTLRenderPipelineState  // Warp speed, pass 2

  /// Generated source file and its entry point: impellerc names it
  /// <shader file name>_fragment_main.
  private static let fragmentShaders: [SaverRenderer: (file: String, function: String)] = [
    .hyperspace: ("HyperspaceSaver", "hyperspace_saver_fragment_main"),
    .procedural: ("ProceduralSaver", "procedural_saver_fragment_main"),
  ]

  private init?() {
    let start = CACurrentMediaTime()
    guard
      let device = MTLCreateSystemDefaultDevice(),
      let queue = device.makeCommandQueue(),
      let vertexSource = Self.resource("FullScreen")
    else {
      log.error("Metal setup failed (device, queue or FullScreen.metal)")
      return nil
    }
    do {
      // One library per source: each includes metal_stdlib and defines helpers.
      let vertexFunction = try device.makeLibrary(source: vertexSource, options: nil).makeFunction(
        name: "fullScreenVertex")
      var pipelines: [SaverRenderer: MTLRenderPipelineState] = [:]
      for (renderer, shader) in Self.fragmentShaders {
        guard let source = Self.resource(shader.file) else {
          log.error("\(shader.file, privacy: .public).metal missing")
          return nil
        }
        let descriptor = MTLRenderPipelineDescriptor()
        descriptor.vertexFunction = vertexFunction
        descriptor.fragmentFunction = try device.makeLibrary(source: source, options: nil).makeFunction(
          name: shader.function)
        descriptor.colorAttachments[0].pixelFormat = .bgra8Unorm
        pipelines[renderer] = try device.makeRenderPipelineState(descriptor: descriptor)
      }
      self.pipelines = pipelines

      // Warp speed: hand-written, with its own vertex stage.
      guard let warpSource = Self.resource("WarpSpeed") else {
        log.error("WarpSpeed.metal missing")
        return nil
      }
      let warp = try device.makeLibrary(source: warpSource, options: nil)
      let nebula = MTLRenderPipelineDescriptor()
      nebula.vertexFunction = warp.makeFunction(name: "warpVertex")
      nebula.fragmentFunction = warp.makeFunction(name: "nebulaFragment")
      nebula.colorAttachments[0].pixelFormat = .rgba16Float
      nebulaPipeline = try device.makeRenderPipelineState(descriptor: nebula)
      let composite = MTLRenderPipelineDescriptor()
      composite.vertexFunction = warp.makeFunction(name: "warpVertex")
      composite.fragmentFunction = warp.makeFunction(name: "warpFragment")
      composite.colorAttachments[0].pixelFormat = .bgra8Unorm
      composite.colorAttachments[1].pixelFormat = Self.historyFormat
      warpPipeline = try device.makeRenderPipelineState(descriptor: composite)
    } catch {
      log.error("shader compile failed: \(error.localizedDescription, privacy: .public)")
      return nil
    }
    self.device = device
    self.queue = queue
    log.notice("Metal ready on \(device.name, privacy: .public) in \((CACurrentMediaTime() - start) * 1000, format: .fixed(precision: 1)) ms")
  }

  private static func resource(_ name: String) -> String? {
    guard let url = Bundle(for: StarfieldsMetalSaverView.self).url(forResource: name, withExtension: "metal") else {
      return nil
    }
    return try? String(contentsOf: url, encoding: .utf8)
  }

  /// A render target for Warp speed's gas clouds.
  func makeNebulaTexture(width: Int, height: Int) -> MTLTexture? {
    let descriptor = MTLTextureDescriptor.texture2DDescriptor(
      pixelFormat: .rgba16Float, width: width, height: height, mipmapped: false)
    descriptor.usage = [.renderTarget, .shaderRead]
    descriptor.storageMode = .private
    return device.makeTexture(descriptor: descriptor)
  }

  /// Warp speed's previous frames: a float format (a fading trail in 8-bit
  /// gets stuck at the lowest values), 4 bytes per pixel, no alpha needed -
  /// two drawable-sized textures per display.
  private static let historyFormat = MTLPixelFormat.rg11b10Float

  func makeHistoryTexture(width: Int, height: Int) -> MTLTexture? {
    let descriptor = MTLTextureDescriptor.texture2DDescriptor(
      pixelFormat: Self.historyFormat, width: width, height: height, mipmapped: false)
    descriptor.usage = [.renderTarget, .shaderRead]
    descriptor.storageMode = .private
    return device.makeTexture(descriptor: descriptor)
  }

  /// Warp speed: the gas clouds into `nebula`, then the composite into the
  /// drawable and `history.write`, blending in `history.read` (the previous
  /// frame; cleared first if `clearHistory`), in one command buffer.
  func drawWarp(
    to drawable: CAMetalDrawable, nebula: MTLTexture, history: (read: MTLTexture, write: MTLTexture),
    clearHistory: Bool, uniforms: WarpUniforms, gpuTime: @escaping (Double) -> Void
  ) {
    guard let buffer = queue.makeCommandBuffer() else { return }
    var u = uniforms
    if clearHistory {
      let clear = MTLRenderPassDescriptor()
      clear.colorAttachments[0].texture = history.read
      clear.colorAttachments[0].loadAction = .clear
      clear.colorAttachments[0].clearColor = MTLClearColor(red: 0, green: 0, blue: 0, alpha: 0)
      clear.colorAttachments[0].storeAction = .store
      buffer.makeRenderCommandEncoder(descriptor: clear)?.endEncoding()
    }
    let gasPass = MTLRenderPassDescriptor()
    gasPass.colorAttachments[0].texture = nebula
    gasPass.colorAttachments[0].loadAction = .dontCare
    gasPass.colorAttachments[0].storeAction = .store
    if let encoder = buffer.makeRenderCommandEncoder(descriptor: gasPass) {
      encoder.setRenderPipelineState(nebulaPipeline)
      encoder.setFragmentBytes(&u, length: MemoryLayout<WarpUniforms>.stride, index: 0)
      encoder.drawPrimitives(type: .triangle, vertexStart: 0, vertexCount: 3)
      encoder.endEncoding()
    }
    let pass = MTLRenderPassDescriptor()
    pass.colorAttachments[0].texture = drawable.texture
    pass.colorAttachments[0].loadAction = .dontCare
    pass.colorAttachments[0].storeAction = .store
    pass.colorAttachments[1].texture = history.write
    pass.colorAttachments[1].loadAction = .dontCare
    pass.colorAttachments[1].storeAction = .store
    guard let encoder = buffer.makeRenderCommandEncoder(descriptor: pass) else { return }
    encoder.setRenderPipelineState(warpPipeline)
    encoder.setFragmentBytes(&u, length: MemoryLayout<WarpUniforms>.stride, index: 0)
    encoder.setFragmentTexture(nebula, index: 0)
    encoder.setFragmentTexture(history.read, index: 1)
    encoder.drawPrimitives(type: .triangle, vertexStart: 0, vertexCount: 3)
    encoder.endEncoding()
    buffer.present(drawable)
    buffer.addCompletedHandler { buffer in gpuTime((buffer.gpuEndTime - buffer.gpuStartTime) * 1000) }
    buffer.commit()
  }

  /// Encodes and presents one frame of `renderer`; `bind` sets its fragment
  /// uniforms, `fragCoordSize` is the size FullScreen.metal spreads
  /// FlutterFragCoord over. `gpuTime` gets the GPU time in ms (on a Metal
  /// thread).
  func draw(
    _ renderer: SaverRenderer, to drawable: CAMetalDrawable, fragCoordSize: SIMD2<Float>,
    gpuTime: @escaping (Double) -> Void, bind: (MTLRenderCommandEncoder) -> Void
  ) {
    let pass = MTLRenderPassDescriptor()
    pass.colorAttachments[0].texture = drawable.texture
    pass.colorAttachments[0].loadAction = .dontCare
    pass.colorAttachments[0].storeAction = .store
    guard let pipeline = pipelines[renderer], let buffer = queue.makeCommandBuffer(),
      let encoder = buffer.makeRenderCommandEncoder(descriptor: pass)
    else { return }
    encoder.setRenderPipelineState(pipeline)
    var size = fragCoordSize
    encoder.setVertexBytes(&size, length: MemoryLayout<SIMD2<Float>>.size, index: 0)
    bind(encoder)
    encoder.drawPrimitives(type: .triangle, vertexStart: 0, vertexCount: 3)
    encoder.endEncoding()
    buffer.present(drawable)
    buffer.addCompletedHandler { buffer in gpuTime((buffer.gpuEndTime - buffer.gpuStartTime) * 1000) }
    buffer.commit()
  }
}

/// Frames per second, CPU and GPU time per frame, reported every 2 s.
private struct FrameStats {
  private var windowStart = CACurrentMediaTime()
  private var frames = 0
  private var cpuMillis = 0.0
  private var gpuFrames = 0
  private var gpuMillis = 0.0
  private var gpuMaxMillis = 0.0
  var ticks = 0  // animateOneFrame calls
  var missedDrawables = 0

  mutating func frame(cpuMillis: Double) {
    frames += 1
    self.cpuMillis += cpuMillis
  }

  mutating func gpuFrame(millis: Double) {
    gpuFrames += 1
    gpuMillis += millis
    gpuMaxMillis = max(gpuMaxMillis, millis)
  }

  mutating func report(now: CFTimeInterval) -> String? {
    let elapsed = now - windowStart
    guard elapsed >= 2 else { return nil }
    let text = String(
      format: "fps %.1f, ticks/s %.1f, cpu %.2f ms/frame, gpu %.2f ms avg %.2f max, missed drawables %d",
      Double(frames) / elapsed, Double(ticks) / elapsed, frames > 0 ? cpuMillis / Double(frames) : 0,
      gpuFrames > 0 ? gpuMillis / Double(gpuFrames) : 0, gpuMaxMillis, missedDrawables)
    self = FrameStats()
    return text
  }
}
